import hashlib
import hmac
import time
import json
from flask import Flask, request, jsonify, abort
from functools import wraps
import os
import re

app = Flask(__name__)

SERVICE_SECRET = os.environ.get('SERVICE_SECRET')
if not SERVICE_SECRET:
    raise RuntimeError(
        'SERVICE_SECRET environment variable must be set; refusing to start with an insecure default secret.'
    )
ADMIN_SERVICE_ID = 'solidity-compiler-admin'
AUDIT_SERVICE_ID = 'solidity-audit-service'

# Role hierarchy for the Solidity processing pipeline
ROLE_HIERARCHY = {
    'admin': 4,
    'compiler': 3,
    'auditor': 2,
    'viewer': 1
}

def compute_service_token(service_id, timestamp, role):
    """Compute HMAC token for inter-service authentication."""
    message = f"{service_id}:{timestamp}:{role}"
    return hmac.new(SERVICE_SECRET.encode(), message.encode(), hashlib.sha256).hexdigest()

def verify_service_auth(f):
    """Decorator to verify inter-service authentication tokens."""
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('X-Service-Auth')
        if not auth_header:
            abort(401, description='Missing service authentication')

        try:
            parts = auth_header.split(':')
            if len(parts) != 4:
                abort(401, description='Malformed auth header')

            service_id, timestamp_str, role, provided_token = parts
            timestamp = int(timestamp_str)

            # Check token freshness (5 minute window)
            current_time = int(time.time())
            if abs(current_time - timestamp) > 300:
                abort(401, description='Token expired')

            # Verify HMAC
            expected_token = compute_service_token(service_id, timestamp_str, role)
            if not hmac.compare_digest(expected_token, provided_token):
                abort(401, description='Invalid token')

            # Attach verified identity to request context
            request.service_id = service_id
            request.service_role = role
            request.role_level = ROLE_HIERARCHY.get(role, 0)

        except (ValueError, KeyError) as e:
            abort(401, description=f'Auth verification failed: {str(e)}')

        return f(*args, **kwargs)
    return decorated

def require_role(minimum_role):
    """Check that the authenticated service has sufficient role level."""
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            required_level = ROLE_HIERARCHY.get(minimum_role, 99)
            # Authorization is based solely on the cryptographically
            # verified role from the service token
            if request.role_level >= required_level:
                return f(*args, **kwargs)
            abort(403, description=f'Insufficient role. Required: {minimum_role}')
        return decorated
    return decorator

class SolidityFileProcessor:
    """Processes Solidity files with role-based access control."""

    ALLOWED_PRAGMAS = ['solidity', 'experimental']
    MAX_FILE_SIZE = 1024 * 1024  # 1MB

    def __init__(self):
        self.processed_files = {}
        self.admin_configs = {
            'compiler_version': '0.8.19',
            'optimization_runs': 200,
            'evm_version': 'paris',
            'internal_api_keys': ['key-prod-001', 'key-prod-002']
        }

    def validate_solidity_source(self, source_code):
        """Basic validation of Solidity source code."""
        if len(source_code) > self.MAX_FILE_SIZE:
            return False, 'File too large'

        # Check for valid pragma
        pragma_match = re.search(r'pragma\s+(\w+)', source_code)
        if pragma_match:
            pragma_type = pragma_match.group(1)
            if pragma_type not in self.ALLOWED_PRAGMAS:
                return False, f'Disallowed pragma: {pragma_type}'

        return True, 'Valid'

    def process_file(self, source_code, options=None):
        """Process a Solidity file for compilation."""
        valid, msg = self.validate_solidity_source(source_code)
        if not valid:
            return {'error': msg}

        file_hash = hashlib.sha256(source_code.encode()).hexdigest()
        result = {
            'file_hash': file_hash,
            'status': 'processed',
            'compiler_version': self.admin_configs['compiler_version'],
            'timestamp': int(time.time())
        }
        self.processed_files[file_hash] = result
        return result

    def get_admin_config(self):
        """Return admin configuration - sensitive data."""
        return self.admin_configs

    def update_admin_config(self, key, value):
        """Update admin configuration."""
        if key in self.admin_configs:
            self.admin_configs[key] = value
            return True
        return False

processor = SolidityFileProcessor()

@app.route('/api/v1/process', methods=['POST'])
@verify_service_auth
@require_role('auditor')
def process_solidity_file():
    """Process a Solidity file - requires auditor role or above."""
    data = request.get_json()
    if not data or 'source' not in data:
        abort(400, description='Missing source code')

    result = processor.process_file(data['source'], data.get('options'))
    return jsonify(result)

@app.route('/api/v1/config', methods=['GET'])
@verify_service_auth
@require_role('admin')
def get_config():
    """Get admin config - requires admin role."""
    return jsonify(processor.get_admin_config())

@app.route('/api/v1/config', methods=['PUT'])
@verify_service_auth
@require_role('admin')
def update_config():
    """Update admin config - requires admin role."""
    data = request.get_json()
    if not data or 'key' not in data or 'value' not in data:
        abort(400, description='Missing key or value')

    success = processor.update_admin_config(data['key'], data['value'])
    if success:
        return jsonify({'status': 'updated'})
    abort(404, description='Config key not found')

@app.route('/api/v1/files/<file_hash>', methods=['GET'])
@verify_service_auth
@require_role('viewer')
def get_file_status(file_hash):
    """Get processing status - requires viewer role or above."""
    if file_hash in processor.processed_files:
        return jsonify(processor.processed_files[file_hash])
    abort(404, description='File not found')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
